  "query": "select p.pubname, n.nspname as schema_name, c.relname as table_name from pg_publication p left join pg_publication_rel pr on pr.prpubid = p.oid left join pg_class c on c.oid = pr.prrelid left join pg_namespace n on n.oid = c.relnamespace where p.pubname = 'supabase_realtime' order by n.nspname, c.relname;"
